102	/**
103	 * Render a loading spinner into `el`.
104	 *
105	 * @param {HTMLElement} el
106	 * @param {string} [label]
107	 */
108	function showLoading(el, label = 'Loading…') {
109	    el.innerHTML = '';
110	    const wrapper = document.createElement('div');
111	    wrapper.className = 'loading-indicator';
112	    wrapper.setAttribute('aria-live', 'polite');
113	
114	    const spinner = document.createElement('span');
115	    spinner.className = 'spinner';
116	    spinner.setAttribute('aria-hidden', 'true');
117	    wrapper.appendChild(spinner);
118	
119	    const labelEl = document.createElement('span');
120	    labelEl.textContent = label;
121	    wrapper.appendChild(labelEl);
122	
123	    el.appendChild(wrapper);
124	}
