130	/**
131	 * Run workspace setup and show appropriate toast notification.
132	 *
133	 * @param {string} projectId
134	 * @param {string} workspaceId
135	 * @param {string} successMessage - Toast message shown when all repos succeed.
136	 * @returns {Promise<Object>} The setup result from the API.
137	 * @throws {Error} Re-throws API errors for the caller to handle.
138	 */
139	async function runSetup(projectId, workspaceId, successMessage) {
140	    const result = await api.workspaces.setup(projectId, workspaceId);
141	    const failures = (result && result.results || []).filter((r) => !r.success);
142	    if (failures.length > 0) {
143	        const names = failures.map((f) => f.repositoryId).join(', ');
144	        showToast(`Setup complete with errors. Failed to clone: ${names}`, 'warning', 8000);
145	    } else {
146	        showToast(successMessage, 'success');
147	    }
148	    return result;
149	}
