155	/**
156	 * Build the status `<tbody>` row for a single repository.
157	 *
158	 * The row uses `data-repo-id` on the badge container so the polling update
159	 * can locate and replace badge contents in-place.
160	 *
161	 * @param {string} repoId
162	 * @param {string} repoName
163	 * @param {Object|null} statusInfo - GitStatusInfo or null.
164	 * @returns {HTMLTableRowElement}
165	 */
166	function buildRepoStatusRow(repoId, repoName, statusInfo) {
167	    const tr = document.createElement('tr');
168	    tr.dataset.repoId = repoId;
169	
170	    // Repository name / ID
171	    const nameCell = document.createElement('td');
172	    nameCell.className = 'repo-name-cell';
173	    const nameEl = document.createElement('span');
174	    nameEl.className = 'repo-name';
175	    nameEl.textContent = repoName;
176	    if (repoName !== repoId) {
177	        const idHint = document.createElement('span');
178	        idHint.className = 'text-muted repo-id-hint';
179	        idHint.textContent = ` (${repoId})`;
180	        nameEl.appendChild(idHint);
181	    }
182	    nameCell.appendChild(nameEl);
183	    tr.appendChild(nameCell);
184	
185	    // Branch name
186	    const branchCell = document.createElement('td');
187	    branchCell.className = 'repo-branch-cell';
188	    branchCell.textContent = (statusInfo && statusInfo.currentBranch)
189	        ? statusInfo.currentBranch
190	        : '—';
191	    tr.appendChild(branchCell);
192	
193	    // Status badge cell
194	    const badgeCell = document.createElement('td');
195	    badgeCell.className = 'repo-badge-cell';
196	
197	    const badgeWrapper = document.createElement('div');
198	    badgeWrapper.dataset.repoId = repoId;
199	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
200	    badgeCell.appendChild(badgeWrapper);
201	    tr.appendChild(badgeCell);
202	
203	    return tr;
204	}
