206	/**
207	 * Update an existing status table in-place by replacing badge contents and
208	 * branch text for each repository whose status has changed.
209	 *
210	 * Rows are located via `[data-repo-id]` on both the `<tr>` and the badge
211	 * wrapper `<div>` inside it. No full re-render of the table is performed.
212	 *
213	 * @param {HTMLElement}           tableBody - The `<tbody>` to update.
214	 * @param {Record<string, Object|null>} statusMap - Keyed by repository ID.
215	 */
216	function updateStatusTable(tableBody, statusMap) {
217	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
218	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
219	        if (!row) continue;
220	
221	        // Update branch cell (second cell)
222	        const branchCell = row.cells[1];
223	        if (branchCell) {
224	            branchCell.textContent = (statusInfo && statusInfo.currentBranch)
225	                ? statusInfo.currentBranch
226	                : '—';
227	        }
228	
229	        // Update badge wrapper (third cell → div[data-repo-id])
230	        const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
231	        if (badgeWrapper) {
232	            badgeWrapper.innerHTML = '';
233	            badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
234	        }
235	    }
236	}
