242	/**
243	 * Build the rename workspace inline form and wire up its event handlers.
244	 *
245	 * @param {string} projectId
246	 * @param {{ id: string }} workspace
247	 * @param {HTMLButtonElement} renameBtn - The "Rename" button that toggles form visibility.
248	 * @returns {HTMLElement}
249	 */
250	function buildRenameForm(projectId, workspace, renameBtn) {

251	    const wrapper = document.createElement('div');
252	    wrapper.className = 'rename-workspace-form-wrapper card';
253	    wrapper.hidden = true;
254	
255	    const formTitle = document.createElement('h4');
256	    formTitle.className   = 'form-section-title';
257	    formTitle.textContent = 'Rename Workspace';
258	    wrapper.appendChild(formTitle);
259	
260	    const newIdField = createFormField('New Workspace ID', 'text', 'newWorkspaceId', {
261	        required:    true,
262	        placeholder: 'e.g. DEV or FEATURE',
263	        hint:        'Must be 2–10 uppercase letters (A-Z only).',
264	    });
265	    wrapper.appendChild(newIdField);
266	
267	    const newIdInput   = newIdField.querySelector('[name="newWorkspaceId"]');
268	    const newIdErrorEl = newIdField.querySelector('.field-error');
269	
270	    const formActions = document.createElement('div');
271	    formActions.className = 'form-actions';
272	
273	    const saveBtn = document.createElement('button');
274	    saveBtn.type      = 'button';
275	    saveBtn.className = 'btn btn-primary btn-sm';
276	    saveBtn.textContent = 'Save';
277	
278	    const cancelFormBtn = document.createElement('button');
279	    cancelFormBtn.type      = 'button';
280	    cancelFormBtn.className = 'btn btn-secondary btn-sm';
281	    cancelFormBtn.textContent = 'Cancel';
282	
283	    formActions.appendChild(saveBtn);
284	    formActions.appendChild(cancelFormBtn);
285	    wrapper.appendChild(formActions);
286	
287	    // Behaviour
288	    renameBtn.addEventListener('click', () => {
289	        wrapper.hidden = false;
290	        if (newIdInput) newIdInput.focus();
291	    });
292	
293	    cancelFormBtn.addEventListener('click', () => {
294	        wrapper.hidden = true;
295	        if (newIdInput) newIdInput.value = '';
296	        if (newIdErrorEl) newIdErrorEl.hidden = true;
297	    });
298	
299	    saveBtn.addEventListener('click', async () => {
300	        if (newIdErrorEl) newIdErrorEl.hidden = true;
301	        if (newIdInput) {
302	            newIdInput.classList.remove('error');
303	            newIdInput.removeAttribute('aria-invalid');
304	        }
305	
306	        if (!validateRequired(wrapper, ['newWorkspaceId'])) return;
307	
308	        const newId = newIdInput ? newIdInput.value.trim() : '';
309	
310	        if (!WORKSPACE_ID_PATTERN.test(newId)) {
311	            if (newIdErrorEl) {
312	                newIdErrorEl.textContent = 'Must be 2–10 uppercase letters (A-Z only).';
313	                newIdErrorEl.hidden      = false;
314	            }
315	            if (newIdInput) {
316	                newIdInput.classList.add('error');
317	                newIdInput.setAttribute('aria-invalid', 'true');
318	                newIdInput.focus();
319	            }
320	            return;
321	        }
322	
323	        try {
324	            await showConfirm(
325	                'Rename Workspace',
326	                `Rename workspace "${workspace.id}" to "${newId}"? The page will navigate to the new workspace URL.`,
327	            );
328	        } catch {
329	            return;
330	        }
331	
332	        saveBtn.disabled    = true;
333	        saveBtn.textContent = 'Saving…';
334	
335	        try {
336	            await api.workspaces.rename(projectId, workspace.id, newId);
337	            showToast(`Workspace renamed to "${newId}".`, 'success');
338	            const target = `#/projects/${encodeURIComponent(projectId)}/workspaces/${encodeURIComponent(newId)}`;
339	            if (_router) {
340	                _router.navigate(target);
341	            } else {
342	                location.hash = target;
343	            }
344	        } catch (err) {
345	            showToast(err.message || 'Failed to rename workspace.', 'error');
346	            saveBtn.disabled    = false;
347	            saveBtn.textContent = 'Save';
348	        }
349	    });
350	
351	    return wrapper;
352	}
