354	/**
355	 * Build the workspace header section — compact layout with breadcrumb,
356	 * workspace name, and a meta card for description + management actions.
357	 *
358	 * @param {string} projectId
359	 * @param {{ id: string, description: string, initialized: boolean, folderPath: string }} workspace
360	 * @param {boolean} isStable
361	 * @param {function(): void} [onSetupSuccess] - Called after a successful setup to trigger refresh.
362	 * @returns {HTMLElement}
363	 */
364	function buildHeaderSection(projectId, workspace, isStable, onSetupSuccess) {
365	    const wrapper = document.createElement('div');
366	    wrapper.className = 'workspace-detail-header';
367	
368	    // Breadcrumb
