388	    titleRow.className = 'workspace-meta-top-row';
389	
390	    const titleEl = document.createElement('h1');
391	    titleEl.className   = 'project-meta-name';
392	    titleEl.textContent = workspace.id;
393	    titleRow.appendChild(titleEl);
394	
395	    // Description (inline, muted)
396	    if (workspace.description) {
397	        const descEl = document.createElement('span');
398	        descEl.className   = 'project-meta-id text-muted';
