402	
403	    wrapper.appendChild(titleRow);
404	
405	    // Folder path row (shown when path is available)
406	    if (workspace.folderPath) {
407	        const pathRow = document.createElement('div');
408	        pathRow.className = 'workspace-folder-path-row';
409	
410	        const pathLabel = document.createElement('span');
