431	        setupBtn.className = 'btn btn-primary btn-sm';
432	        setupBtn.textContent = 'Setup Workspace';
433	        setupBtn.title = 'Initialize workspace on disk (create folder, clone repos).';
434	
435	        setupBtn.addEventListener('click', async () => {
436	            setupBtn.disabled = true;
437	            setupBtn.textContent = 'Setting up…';
438	
439	            try {
440	                await runSetup(projectId, workspace.id,
441	                    `Workspace "${workspace.id}" set up successfully.`);
442	
443	                // Update DOM in-place — remove setup button and notify caller
444	                setupBtn.remove();
445	                workspace.initialized = true;
446	                if (onSetupSuccess) onSetupSuccess();
447	            } catch (err) {
448	                showToast(err.message || 'Failed to set up workspace.', 'error');
449	                setupBtn.disabled = false;
450	                setupBtn.textContent = 'Setup Workspace';

451	            }
452	        });
453	        mgmtRow.appendChild(setupBtn);
454	    }
455	
456	    // Rename button (disabled for STABLE)
457	    const renameBtn = document.createElement('button');
458	    renameBtn.type      = 'button';
459	    renameBtn.className = 'btn btn-secondary btn-sm';
460	    renameBtn.textContent = 'Rename';
461	
462	    if (isStable) {
463	        renameBtn.disabled = true;
464	        renameBtn.title    = 'The STABLE workspace cannot be renamed.';
465	    }
466	    mgmtRow.appendChild(renameBtn);
467	
468	    // Delete button (disabled for STABLE)
469	    const deleteBtn = document.createElement('button');
470	    deleteBtn.type      = 'button';
471	    deleteBtn.className = 'btn btn-danger btn-sm';
472	    deleteBtn.textContent = 'Delete';
473	
474	    if (isStable) {
475	        deleteBtn.disabled = true;
476	        deleteBtn.title    = 'The STABLE workspace cannot be deleted.';
477	    }
478	    mgmtRow.appendChild(deleteBtn);
479	
480	    wrapper.appendChild(mgmtRow);
481	
482	    // Rename inline form + delete handler (non-STABLE only)
483	    if (!isStable) {
484	        wrapper.appendChild(buildRenameForm(projectId, workspace, renameBtn));
485	
486	        deleteBtn.addEventListener('click', async () => {
487	            try {
