518	/**
519	 * Build the repository status table section.
520	 *
521	 * @param {Array<{ repoId: string, repoName: string }>} repos
522	 * @param {Record<string, Object|null>} statusMap
523	 * @returns {{ section: HTMLElement, tbody: HTMLTableSectionElement }}
524	 */
