526	    const section = document.createElement('section');
527	    section.className = 'workspace-status-section';
528	
529	    if (repos.length === 0) {
530	        const empty = document.createElement('p');
531	        empty.className   = 'empty-state-inline text-secondary';
532	        empty.textContent = 'No repositories in this project.';
533	        section.appendChild(empty);
534	        return { section, tbody: null };
535	    }
536	
537	    const table = document.createElement('table');
538	    table.className = 'data-table workspace-status-table';
539	
540	    const thead = document.createElement('thead');
541	    const htr   = document.createElement('tr');
542	    ['Repository', 'Branch', 'Status'].forEach((label) => {
543	        const th = document.createElement('th');
544	        th.textContent = label;
545	        htr.appendChild(th);
546	    });
547	    thead.appendChild(htr);
548	    table.appendChild(thead);
549	
550	    const tbody = document.createElement('tbody');
551	
552	    repos.forEach(({ repoId, repoName }) => {
553	        const statusInfo = statusMap[repoId] ?? null;
554	        tbody.appendChild(buildRepoStatusRow(repoId, repoName, statusInfo));
555	    });
556	
557	    table.appendChild(tbody);
558	    section.appendChild(table);
559	
560	    return { section, tbody };
