615	/**
616	 * Build a health alert section element from a workspace health report.
617	 * Returns `null` when the workspace is healthy (no issues to display).
618	 *
619	 * Fix-action buttons are wired via the `callbacks` argument so the
620	 * caller can inject async handlers that match the surrounding view's
621	 * closure state (project/workspace IDs, toast helper, etc.).
622	 *
623	 * @param {{ healthy: boolean, issues: Array<{ type: string, severity: string, message: string, fixAction: string, repositoryId?: string }> }|null} healthReport
624	 * @param {{ onRegenerate: function(): Promise<void>, onSetup: function(): Promise<void> }} callbacks
625	 * @returns {HTMLElement|null}
626	 */
627	function buildHealthAlertSection(healthReport, callbacks) {
628	    if (
629	        !healthReport ||
630	        healthReport.healthy ||
631	        !Array.isArray(healthReport.issues) ||
632	        healthReport.issues.length === 0
633	    ) {
634	        return null;
635	    }
636	
637	    const section = document.createElement('div');
638	    section.className = 'health-alert';
639	
640	    const title = document.createElement('div');
641	    title.className = 'health-alert-title';
642	    title.textContent = 'Workspace health issues detected';
643	    section.appendChild(title);
644	
645	    for (const issue of healthReport.issues) {
646	        const row = document.createElement('div');
647	        row.className = 'health-alert-issue';
648	
649	        const msg = document.createElement('span');
650	        msg.className = 'health-alert-issue__message';

651	        msg.textContent = issue.message;
652	        row.appendChild(msg);
653	
654	        if (issue.fixAction === 'regenerate-workspace-file') {
655	            const actionWrap = document.createElement('span');
656	            actionWrap.className = 'health-alert-issue__action';
657	
658	            const btn = document.createElement('button');
659	            btn.type = 'button';
660	            btn.className = 'btn btn-secondary btn-sm';
661	            btn.textContent = 'Regenerate File';
662	            btn.addEventListener('click', async () => {
663	                btn.disabled = true;
664	                btn.textContent = 'Regenerating\u2026';
665	                try {
666	                    await callbacks.onRegenerate();
667	                } finally {
668	                    btn.disabled = false;
669	                    btn.textContent = 'Regenerate File';
670	                }
671	            });
672	            actionWrap.appendChild(btn);
673	            row.appendChild(actionWrap);
674	        } else if (issue.fixAction === 'setup-workspace') {
675	            const actionWrap = document.createElement('span');
676	            actionWrap.className = 'health-alert-issue__action';
677	
678	            const btn = document.createElement('button');
679	            btn.type = 'button';
680	            btn.className = 'btn btn-secondary btn-sm';
681	            btn.textContent = 'Fix Setup';
682	            btn.addEventListener('click', async () => {
683	                btn.disabled = true;
684	                btn.textContent = 'Setting up\u2026';
685	                try {
686	                    await callbacks.onSetup();
687	                } finally {
688	                    btn.disabled = false;
689	                    btn.textContent = 'Fix Setup';
690	                }
691	            });
692	            actionWrap.appendChild(btn);
693	            row.appendChild(actionWrap);
694	        }
695	        // Issues with an unknown fixAction render the message row without a button.
696	
697	        section.appendChild(row);
698	    }
699	
700	    return section;
701	}
